test('account split requires all opaque source instances, aliases and operations to be distributed explicitly',async({page})=>{
 const h=await setup(page),id=h.state.accounts[0]!.id,source1=crypto.randomUUID(),source2=crypto.randomUUID(),alias=crypto.randomUUID();h.state.accountSources=[source1,source2].map(observationId=>({observationId,transactionId:h.detail.id,originalAccountId:id,assignedAccountId:id}));h.state.accountAliases=[{id:alias,accountId:id,type:'account'}];await page.getByRole('button',{name:'Обновить данные',exact:true}).click();await section(page,'Счета');await page.getByRole('button',{name:'Структура счёта: Тестовый счёт',exact:true}).click();await page.getByLabel('Действие с карточкой',{exact:true}).selectOption('split');await page.getByLabel('Название новой карточки 1',{exact:true}).fill('Отдельный счёт');await page.getByRole('button',{name:'Показать последствия изменения структуры'}).click();await expect(page.getByRole('alert')).toContainText('Распределите каждый источник');expect(h.calls.filter(c=>c.path==='/finance/preview')).toHaveLength(0);const destination=await page.getByLabel(/^Источник 1:/).locator('option').filter({hasText:'Отдельный счёт'}).getAttribute('value');await page.getByLabel(/^Источник 1:/).selectOption(id);await page.getByLabel(/^Источник 2:/).selectOption(destination!);await page.getByLabel(/^Псевдоним 1:/).selectOption(destination!);await page.getByLabel(/^Операция 1:/).selectOption(id);await page.getByRole('button',{name:'Показать последствия изменения структуры'}).click();await expect(page.getByRole('button',{name:'Применить изменение',exact:true})).toBeVisible();expect(h.calls.filter(c=>c.path==='/finance/preview').at(-1)?.body.intent).toMatchObject({kind:'split_account',id,newAccounts:[{id:destination,name:'Отдельный счёт',analyticsEnabled:true}],observations:[{id:source1,accountId:id},{id:source2,accountId:destination}],aliases:[{id:alias,accountId:destination}],operations:[{id:h.detail.id,accountId:id}]});expect(await page.locator('body').innerText()).not.toContain(alias);expect(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)).toBe(false);
});
