test('period deletion uses explicit inclusive dates and chosen accounts independently of global filters',async({page})=>{const h=await setup(page);await deletionFixture(page,h);await section(page,'Конфиденциальность');await page.getByRole('button',{name:'Удалить данные за период',exact:true}).click();await page.getByLabel('Удалить с даты',{exact:true}).fill('2026-09-01');await page.getByLabel('Удалить по дату',{exact:true}).fill('2026-09-30');await page.getByLabel('Счета периода',{exact:true}).selectOption('selected');await page.getByRole('button',{name:'Показать состав удаления',exact:true}).click();await expect(page.getByRole('alert')).toContainText('хотя бы один счёт');await page.getByRole('group',{name:'Выбранные счета периода'}).getByRole('checkbox').check();await page.getByRole('button',{name:'Показать состав удаления',exact:true}).click();expect(h.calls.filter(c=>c.path==='/finance/preview').at(-1)?.body.intent).toEqual({kind:'delete_financial',scope:{kind:'period',from:'2026-09-01',through:'2026-09-30',accountIds:[h.state.accounts[0]!.id]}});await expect(page.getByRole('region',{name:'Состав удаления'})).toContainText('Вся финансовая история');expect(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)).toBe(false);});
test('account and deep counterparty deletion require explicit card choices and show source scope',async({page})=>{const h=await setup(page);await deletionFixture(page,h);await section(page,'Счета');await page.getByRole('button',{name:'Удалить данные счёта: Тестовый счёт',exact:true}).click();await page.getByLabel('Карточка после удаления',{exact:true}).selectOption('keep');await page.getByRole('button',{name:'Показать состав удаления',exact:true}).click();expect(h.calls.filter(c=>c.path==='/finance/preview').at(-1)?.body.intent).toEqual({kind:'delete_financial',scope:{kind:'account',accountId:h.state.accounts[0]!.id,deleteAccount:false}});await page.getByRole('button',{name:'Закрыть без нового удаления',exact:true}).click();await section(page,'Контрагенты');const p=h.state.counterparties[0]!;await page.getByRole('button',{name:'Удалить данные контрагента: '+p.name,exact:true}).click();await page.getByLabel('Карточка после удаления',{exact:true}).selectOption('delete');await page.getByRole('button',{name:'Показать состав удаления',exact:true}).click();expect(h.calls.filter(c=>c.path==='/finance/preview').at(-1)?.body.intent).toEqual({kind:'delete_financial',scope:{kind:'counterparty',counterpartyId:p.id,deleteCard:true}});expect(h.calls.filter(c=>c.path==='/finance/commit')).toHaveLength(0);});
test('physical deletion with a lost response retries the same commit, clears old rows and has no Undo',async({page})=>{const h=await setup(page),merchant=h.state.operations[0]!.classification.merchant.value;const fixture=await deletionFixture(page,h,{lostCommit:true});await page.getByRole('link',{name:'Операции',exact:true}).click();await page.getByLabel('Выбрать операцию 1',{exact:true}).check();await page.getByRole('button',{name:'Удалить выбранные данные',exact:true}).click();await page.getByRole('button',{name:'Показать состав удаления',exact:true}).click();await page.getByRole('button',{name:'Подтвердить физическое удаление',exact:true}).click();await expect(page.getByRole('button',{name:'Закрыть без нового удаления',exact:true})).toBeDisabled();await page.getByRole('button',{name:'Повторить то же удаление',exact:true}).click();await expect(page.getByRole('region',{name:'Удаление завершено'})).toContainText('Данные удалены');expect(fixture.commits).toHaveLength(2);expect(fixture.commits[0]).toEqual(fixture.commits[1]);expect(await page.getByRole('dialog').innerText()).not.toContain(merchant);await page.getByRole('button',{name:'Закрыть результат удаления',exact:true}).click();await expect(page.getByRole('heading',{name:'Здесь будут ваши операции'})).toBeVisible();await expect(page.getByRole('button',{name:'Отменить последнее изменение',exact:true})).toHaveCount(0);});
test('full reset has explicit preservation choices, one password confirmation and clears old interface data',async({page},info)=>{const h=await setup(page);h.state.interfaceEpoch=crypto.randomUUID();await page.getByRole('button',{name:'Обновить данные',exact:true}).click();await section(page,'Интерфейс');await page.getByLabel('Тема',{exact:true}).selectOption('dark');const fixture=await deletionFixture(page,h,{recent:true,wrongPassword:true});await section(page,'Конфиденциальность');await page.getByRole('button',{name:'Открыть полный финансовый сброс',exact:true}).click();await resetChoices(page);await page.getByRole('button',{name:'Показать состав удаления',exact:true}).click();await expect(page.getByRole('region',{name:'Состав удаления'})).toContainText('Правил потребуется настроить заново: 1');expect(h.calls.filter(c=>c.path==='/finance/preview').at(-1)?.body.intent).toEqual({kind:'reset_financial',keepCategories:true,keepRules:true,keepInterface:false});expect(h.calls.filter(c=>c.path==='/finance/epoch')).toHaveLength(1);await page.screenshot({path:info.outputPath('financial-reset-preview.png'),fullPage:true});await page.getByLabel('Пароль для финансового сброса',{exact:true}).fill('Wrong synthetic password');await page.getByRole('button',{name:'Подтвердить полный финансовый сброс',exact:true}).click();await expect(page.getByRole('alert')).toContainText('Проверьте пароль');await expect(page.getByLabel('Пароль для финансового сброса',{exact:true})).toHaveValue('');await page.getByLabel('Пароль для финансового сброса',{exact:true}).fill('Correct synthetic password');await page.getByRole('button',{name:'Подтвердить полный финансовый сброс',exact:true}).click();await expect(page.getByRole('region',{name:'Удаление завершено'})).toContainText('Финансовые данные сброшены');expect(fixture.commits.map(c=>c.actionId)).toEqual([fixture.commits[0]!.actionId,fixture.commits[0]!.actionId]);expect(fixture.commits[1]).toMatchObject({confirmReset:true,password:'Correct synthetic password'});expect(h.calls.filter(c=>c.path==='/finance/preview')).toHaveLength(1);expect(await page.evaluate(()=>localStorage.getItem('finance-appearance-v1'))).toBeNull();expect(await page.evaluate(()=>document.documentElement.dataset.theme)).toBe('system');expect(await page.evaluate(()=>JSON.stringify({...localStorage}))).not.toContain('synthetic password');expect(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)).toBe(false);});
test('changed deletion dependencies discard the preview without deleting or automatically widening scope',async({page})=>{const h=await setup(page);await deletionFixture(page,h);await section(page,'Конфиденциальность');await page.getByRole('button',{name:'Открыть полный финансовый сброс',exact:true}).click();await resetChoices(page,'keep');await page.getByRole('button',{name:'Показать состав удаления',exact:true}).click();await page.route('http://127.0.0.1:3000/finance/commit',async r=>{if(r.request().method()==='OPTIONS')return r.fallback();h.calls.push({path:'/finance/commit',body:r.request().postDataJSON()});await r.fulfill({status:409,headers:{'Access-Control-Allow-Origin':new URL(base).origin,'Access-Control-Allow-Credentials':'true'},json:{code:'DEPENDENCIES_CHANGED'}});});await page.getByRole('button',{name:'Подтвердить полный финансовый сброс',exact:true}).click();await expect(page.getByRole('alert')).toContainText('Ничего не удалено');await expect(page.getByRole('region',{name:'Состав удаления'})).toHaveCount(0);expect(h.state.operations).toHaveLength(1);expect(h.calls.filter(c=>c.path==='/finance/preview')).toHaveLength(1);});
test('large workspace reset opens through the count-only epoch despite a failed graph load',async({page})=>{const h=await setup(page);await deletionFixture(page,h,{large:true});await page.route('http://127.0.0.1:3000/finance/summary',async r=>{if(r.request().method()==='OPTIONS')return r.fallback();await r.fulfill({status:409,headers:{'Access-Control-Allow-Origin':new URL(base).origin,'Access-Control-Allow-Credentials':'true'},json:{code:'FINANCE_SIZE_LIMIT'}});});await page.reload();await page.getByRole('button',{name:'Открыть экраны приложения'}).click();await page.getByRole('button',{name:'Открыть полный финансовый сброс',exact:true}).click();await resetChoices(page,'keep');await page.getByRole('button',{name:'Показать состав удаления',exact:true}).click();await expect(page.getByRole('region',{name:'Состав удаления'})).toContainText('10001');await page.getByRole('button',{name:'Подтвердить полный финансовый сброс',exact:true}).click();await expect(page.getByRole('region',{name:'Удаление завершено'})).toContainText('10001');expect(h.calls.filter(c=>c.path==='/finance/epoch')).toHaveLength(1);});
test('an interface epoch changed on another device resets stored appearance on the next refresh',async({page})=>{const h=await setup(page);h.state.interfaceEpoch=crypto.randomUUID();await page.getByRole('button',{name:'Обновить данные',exact:true}).click();await section(page,'Интерфейс');await page.getByLabel('Тема',{exact:true}).selectOption('dark');const epoch=crypto.randomUUID();h.state.interfaceEpoch=epoch;h.state.generation=crypto.randomUUID();h.state.operations=[];await page.getByRole('button',{name:'Обновить данные',exact:true}).click();await expect(page.getByLabel('Тема',{exact:true})).toHaveValue('system');expect(await page.evaluate(()=>localStorage.getItem('finance-interface-epoch-v1'))).toBe(epoch);expect(await page.evaluate(()=>localStorage.getItem('finance-appearance-v1'))).toBeNull();await page.reload();await page.getByRole('button',{name:'Открыть экраны приложения'}).click();await expect(page.getByLabel('Тема',{exact:true})).toHaveValue('system');});

test('local CSV XLSX OCR upload dialog remains readable on desktop and mobile',async({page},testInfo)=>{
 await setup(page);await page.getByRole('button',{name:'Загрузить файлы',exact:true}).click();const dialog=page.getByRole('dialog',{name:'Загрузка выписок'});await expect(dialog.getByLabel('Файлы выписок')).toHaveAttribute('accept','.pdf,.csv,.xlsx');await expect(dialog).toContainText('PDF, CSV или XLSX');await expect(dialog).toContainText('Файл и пароль остаются на устройстве');expect(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)).toBe(false);await dialog.screenshot({path:testInfo.outputPath('local-import-preview.png')});
});


test('changing shared dates preserves Operations settings, hides stale totals, and manual all-history overrides a dynamic period',async({page})=>{
 await setup(page);await page.getByRole('link',{name:'Операции',exact:true}).click();
 const region=page.getByRole('region',{name:'Проверка и выбор операций'}),list=page.getByRole('list',{name:'Сохранённые операции'});
 await expect(list.getByRole('listitem')).toHaveCount(1);await page.getByLabel('Поиск сохранённых операций').fill('Synthetic shop');await page.getByLabel('Плотность операций').selectOption('compact');
 let release!:()=>void,started!:()=>void;const gate=new Promise<void>(resolve=>{release=resolve;}),begin=new Promise<void>(resolve=>{started=resolve;});
 await page.route('http://127.0.0.1:3000/finance/operations-page',async route=>{if(route.request().method()==='POST'&&route.request().postDataJSON().query.filter.from==='2099-01-01'){started();await gate;}await route.fallback();});
 await page.getByLabel('С даты',{exact:true}).fill('2099-01-01');await begin;
 try{await expect(page.getByLabel('Поиск сохранённых операций')).toHaveValue('Synthetic shop');await expect(page.getByLabel('Плотность операций')).toHaveValue('compact');await expect(region.getByText(/^Расходы:/)).toHaveCount(0);await expect(list).toHaveCount(0);await expect(page.getByRole('button',{name:'Выбрать все найденные',exact:true})).toBeDisabled();}finally{release();}
 await expect(page.getByRole('heading',{name:'Нет операций по выбранным фильтрам'})).toBeVisible();await page.getByRole('button',{name:'За всю историю',exact:true}).click();await expect(list.getByRole('listitem')).toHaveCount(1);
 await page.clock.setFixedTime(new Date('2026-10-10T12:00:00Z'));await page.getByLabel('Период представления').selectOption('last_30_days');await expect(page.getByLabel('С даты',{exact:true})).toHaveValue('2026-09-11');await expect(page.getByRole('heading',{name:'Нет операций по выбранным фильтрам'})).toBeVisible();await page.getByRole('button',{name:'За всю историю',exact:true}).click();await expect(page.getByLabel('Период представления')).toHaveValue('all');await expect(page.getByLabel('С даты',{exact:true})).toHaveValue('');await expect(list.getByRole('listitem')).toHaveCount(1);await expect(page.getByLabel('Поиск сохранённых операций')).toHaveValue('Synthetic shop');
});


test('a delayed default view cannot overwrite a search already entered in Operations',async({page})=>{
 await setup(page);let release!:()=>void,started!:()=>void;const gate=new Promise<void>(resolve=>{release=resolve;}),begin=new Promise<void>(resolve=>{started=resolve;});
 await page.route('http://127.0.0.1:3000/finance/operations-views',async route=>{if(route.request().method()==='OPTIONS')return route.fallback();started();await gate;await route.fulfill({headers:{'Access-Control-Allow-Origin':new URL(base).origin,'Access-Control-Allow-Credentials':'true'},json:{views:[{id:crypto.randomUUID(),name:'Synthetic delayed default',isDefault:true,dependencyStatus:'ready',revision:'1',position:0,modifiedAt:'2026-10-10T12:00:00Z',definition:{filter:{search:'Never matching synthetic'},period:'all',columns:['merchant','amount'],widths:{},sort:'date',direction:'desc',group:'none',density:'compact'}}]}});});
 await page.getByRole('link',{name:'Операции',exact:true}).click();await begin;await page.getByLabel('Поиск сохранённых операций').fill('Synthetic shop');await expect(page.getByRole('list',{name:'Сохранённые операции'}).getByRole('listitem')).toHaveCount(1);
 const response=page.waitForResponse(r=>r.url().endsWith('/finance/operations-views')&&r.request().method()==='POST');release();await response;await expect(page.getByLabel('Представление операций')).toContainText('Synthetic delayed default');await expect(page.getByLabel('Поиск сохранённых операций')).toHaveValue('Synthetic shop');await expect(page.getByLabel('Представление операций')).toHaveValue('');await expect(page.getByRole('list',{name:'Сохранённые операции'}).getByRole('listitem')).toHaveCount(1);
});
